import "./Modal.css";

const Modal = ({ comment, btn1, btn2 }) => {
  return (
    <div>
      <h4>{comment}</h4>
      <div className="buttons">
        <button>{btn1}</button>
        <button>{btn2}</button>
      </div>
    </div>
  );
};

export default Modal;
